def row(order,y=350,labels=False,variant=0):
 e=[]
 for i,k in enumerate(order):
  e.append(solid(k,100+130*i,y,.65,variant+2*i))
  if labels:e.append(text(k.replace('non-cube ','non-cube<br/>'),y+100,13,48+130*i,120))
 return e
